<?php require_once __DIR__.'/config/database.php';require_once __DIR__.'/config/auth.php';require_page('cpoe.php');$page_title='CPOE / Clinical Orders';$page_subtitle=is_role('doctor')?'Dokter membuat order klinis. Unit pelaksana hanya memproses order sesuai jenis layanan.':'Worklist klinis sesuai unit Anda.';$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'';
 if($action==='create'&&is_role('doctor')){$did=doctor_id($pdo);$eid=(int)$_POST['encounter_id'];$s=$pdo->prepare('SELECT id,patient_id,doctor_id FROM encounters WHERE id=? AND doctor_id=?');$s->execute([$eid,$did]);$e=$s->fetch();if(!$e){$msg='Encounter bukan milik Anda.';}else{$q=$pdo->prepare('INSERT INTO cpoe_orders(encounter_id,patient_id,ordered_by,order_type,priority,order_name,clinical_indication,instructions) VALUES(?,?,?,?,?,?,?,?)');$q->execute([$eid,$e['patient_id'],current_user_id(),$_POST['order_type'],$_POST['priority'],trim($_POST['order_name']),trim($_POST['clinical_indication']),trim($_POST['instructions'])]);audit($pdo,'CREATE','CPOE',(int)$pdo->lastInsertId(),'Clinical order dibuat dokter.');$msg='Order berhasil dikirim ke unit terkait.';}}
 elseif($action==='status'&&(is_role('laboratory')||is_role('radiology'))){$id=(int)$_POST['id'];$status=$_POST['status']??'';$type=is_role('laboratory')?'laboratory':'radiology';if(!in_array($status,['acknowledged','in_progress','completed'],true))$msg='Status order tidak valid.';else{$s=$pdo->prepare("UPDATE cpoe_orders SET status=?,completed_at=IF(?='completed',NOW(),completed_at) WHERE id=? AND order_type=?");$s->execute([$status,$status,$id,$type]);audit($pdo,'UPDATE','CPOE',$id,'Status order '.$type.' menjadi '.$status);$msg='Status order diperbarui.';}}
}
$enc=[];if(is_role('doctor')){$s=$pdo->prepare("SELECT e.id,e.patient_id,p.name,p.mrn FROM encounters e JOIN patients p ON p.id=e.patient_id WHERE e.doctor_id=? AND e.clinical_status IN ('draft','signed','amended') ORDER BY e.encounter_date DESC");$s->execute([doctor_id($pdo)]);$enc=$s->fetchAll();}
$where='';$params=[];if(is_role('doctor')){$where='WHERE o.ordered_by=?';$params=[current_user_id()];}elseif(is_role('laboratory')){$where="WHERE o.order_type='laboratory'";}elseif(is_role('radiology')){$where="WHERE o.order_type='radiology'";}else{$where='';}
$sql="SELECT o.*,p.name patient,p.mrn,u.name ordered_by_name FROM cpoe_orders o JOIN patients p ON p.id=o.patient_id JOIN users u ON u.id=o.ordered_by $where ORDER BY FIELD(o.priority,'stat','urgent','routine'),o.ordered_at DESC";$s=$pdo->prepare($sql);$s->execute($params);$orders=$s->fetchAll();include __DIR__.'/includes/header.php';?>
<?php if($msg):?><div class="alert <?=str_contains($msg,'berhasil')||str_contains($msg,'diperbarui')?'success':'danger'?>"><?=h($msg)?></div><?php endif;?>
<div class="grid two"><?php if(is_role('doctor')):?><div class="card"><div class="card-header"><div><h3 class="section-title">New Clinical Order</h3><p class="section-subtitle">CPOE hanya dapat dibuat oleh dokter dari encounter yang menjadi tanggung jawabnya.</p></div></div><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="create"><div class="form-grid"><div style="grid-column:1/-1"><label>Encounter</label><select name="encounter_id" required><option value="">Pilih encounter</option><?php foreach($enc as $e):?><option value="<?=$e['id']?>">#<?=$e['id']?> — <?=h($e['mrn'].' '.$e['name'])?></option><?php endforeach;?></select></div><div><label>Jenis Order</label><select name="order_type"><option value="laboratory">Laboratory</option><option value="radiology">Radiology</option><option value="procedure">Procedure</option><option value="medication">Medication</option></select></div><div><label>Prioritas</label><select name="priority"><option value="routine">Routine</option><option value="urgent">Urgent</option><option value="stat">STAT</option></select></div><div style="grid-column:1/-1"><label>Order Name</label><input name="order_name" required placeholder="CBC / Foto Toraks PA / USG"></div><div style="grid-column:1/-1"><label>Clinical Indication</label><textarea name="clinical_indication" required></textarea></div><div style="grid-column:1/-1"><label>Instructions</label><textarea name="instructions"></textarea></div><div><button class="btn primary">Kirim Clinical Order</button></div></div></form></div><div class="card"><?php else:?><div class="card" style="grid-column:1/-1"><?php endif;?><div class="card-header"><div><h3 class="section-title">Order Worklist</h3><p class="section-subtitle"><?=count($orders)?> order dalam scope.</p></div></div><div class="table-wrap"><table><tr><th>Pasien</th><th>Order</th><th>Priority</th><th>Ordering</th><th>Status</th><th>Workflow</th></tr><?php foreach($orders as $o):?><tr><td><?=h($o['patient'])?><br><span class="mini"><?=h($o['mrn'])?></span></td><td><b><?=h($o['order_name'])?></b><br><span class="mini"><?=h($o['order_type'])?></span></td><td><span class="badge <?=$o['priority']==='stat'?'danger':($o['priority']==='urgent'?'warn':'info')?>"><?=h(strtoupper($o['priority']))?></span></td><td><?=h($o['ordered_by_name'])?></td><td><?=h($o['status'])?></td><td><?php if((is_role('laboratory')&&$o['order_type']==='laboratory')||(is_role('radiology')&&$o['order_type']==='radiology')):?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status" onchange="this.form.submit()"><option value="acknowledged">acknowledged</option><option value="in_progress">in_progress</option><option value="completed">completed</option></select></form><?php else:?><span class="mini">Read-only</span><?php endif;?></td></tr><?php endforeach;?></table></div></div></div><?php include __DIR__.'/includes/footer.php';?>